import{c as a,Q as s,j as i,m as t}from"./chunks/framework.BPKcPtvA.js";const g=JSON.parse('{"title":"Internet bridge","description":"","frontmatter":{},"headers":[],"relativePath":"docs/bridge.md","filePath":"docs/bridge.md"}'),n={name:"docs/bridge.md"};function r(p,e,h,o,l,d){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="internet-bridge" tabindex="-1">Internet bridge <a class="header-anchor" href="#internet-bridge" aria-label="Permalink to &quot;Internet bridge&quot;">​</a></h1><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>Two LoRa networks that cannot hear each other can exchange messages over the internet. Repeaters on both sides connect to a shared TCP server. Packets received via LoRa are forwarded to all remote repeaters; packets from remote repeaters are injected back into the local LoRa mesh.</p><p>Users and apps do not notice the bridge. They use LoRa as normal.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[LoRa mesh A]  ←→  [Repeater A]  ←→  internet  ←→  [Repeater B]  ←→  [LoRa mesh B]</span></span></code></pre></div><h2 id="path-1-esp32-repeater-with-wifi" tabindex="-1">Path 1: ESP32 repeater with WiFi <a class="header-anchor" href="#path-1-esp32-repeater-with-wifi" aria-label="Permalink to &quot;Path 1: ESP32 repeater with WiFi&quot;">​</a></h2><p>Flash a <code>_bridge_tcp</code> firmware variant on an ESP32 repeater that has WiFi, then configure it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set wifi.ssid     YourWiFi</span></span>
<span class="line"><span>set wifi.password secret123</span></span>
<span class="line"><span>set bridge.server yourserver.example.com</span></span>
<span class="line"><span>set bridge.port   4200</span></span>
<span class="line"><span>set bridge.enabled on</span></span></code></pre></div><p>Check the bridge type:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>get bridge.type</span></span></code></pre></div><h2 id="path-2-repeater-via-usb" tabindex="-1">Path 2: Repeater via USB <a class="header-anchor" href="#path-2-repeater-via-usb" aria-label="Permalink to &quot;Path 2: Repeater via USB&quot;">​</a></h2><p>Boards without WiFi — nRF52 (RAK4631), RP2040, STM32, or ESP32 boards without WiFi access — can also participate via USB.</p><p>Flash the <code>_bridge_rs232</code> firmware variant and enable the bridge:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set bridge.enabled on</span></span></code></pre></div><p>Then run the relay script on a connected PC or Raspberry Pi:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pyserial</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/usb_bridge_client.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --serial</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/ttyUSB0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --baud</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 115200</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">                                    --server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yourserver.example.com</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4200</span></span></code></pre></div><p>On Windows use <code>--serial COM3</code>.</p><h2 id="running-the-server" tabindex="-1">Running the server <a class="header-anchor" href="#running-the-server" aria-label="Permalink to &quot;Running the server&quot;">​</a></h2><p>Start the TCP bridge server on any internet-connected machine with Python 3.7+:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/tcp_bridge_server.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4200</span></span></code></pre></div><p>No external dependencies. WiFi repeaters and USB repeaters can connect to the same server simultaneously.</p><h2 id="security-note" tabindex="-1">Security note <a class="header-anchor" href="#security-note" aria-label="Permalink to &quot;Security note&quot;">​</a></h2><p>The current TCP bridge does not encrypt traffic. Run the server on a trusted network or VPS with firewall rules limiting access. TLS support is planned for a future release.</p>`,23)])])}const k=a(n,[["render",r]]);export{g as __pageData,k as default};
